export const publishedDreamDictionaryEntries = dreamDictionaryEntries.filter((entry) => entry.published);

export function getDreamDictionaryEntry(slug: string) {
  return publishedDreamDictionaryEntries.find((entry) => entry.slug === slug);
}

export function getRelatedDreamDictionaryEntries(entry: DreamDictionaryEntry) {
  return entry.relatedDreams
    .map((slug) => getDreamDictionaryEntry(slug))
    .filter((item): item is DreamDictionaryEntry => Boolean(item));
}
